1	import http from 'node:http';
2	import { URL } from 'node:url';
3	
4	import { canonicalJson } from './canonical.js';
5	import { CachelatticeError, NotFoundError, ValidationError } from './errors.js';
6	import { Cachelattice, assertCacheKey } from './service.js';
7	
8	const MAX_BODY = 4 * 1024 * 1024;
9	
10	const JSON_HEADERS = { 'content-type': 'application/json; charset=utf-8' };
11	const OCTET_HEADERS = { 'content-type': 'application/octet-stream' };
12	
13	function readBody(request) {
14	  return new Promise((resolve, reject) => {
15	    const chunks = [];
16	    let size = 0;
17	    request.on('data', (chunk) => {
18	      size += chunk.length;
19	      if (size > MAX_BODY) {
20	        reject(new ValidationError('request body exceeds 4194304 bytes'));
21	        request.destroy();
22	        return;
23	      }
24	      chunks.push(chunk);
25	    });
26	    request.on('end', () => resolve(Buffer.concat(chunks)));
27	    request.on('error', reject);
28	  });
29	}
30	
31	function parseJson(buffer) {
32	  if (buffer.length === 0) throw new ValidationError('request body must be JSON');
33	  try {
34	    return JSON.parse(buffer.toString('utf8'));
35	  } catch {
36	    throw new ValidationError('request body must be valid JSON');
37	  }
38	}
39	
40	export function createServer(service) {
41	  const server = http.createServer(async (request, response) => {
42	    const url = new URL(request.url, 'http://127.0.0.1');
43	    const segments = url.pathname.split('/').filter((segment) => segment.length > 0);
44	    const idempotencyKey = request.headers['idempotency-key'];
45	    let status = 200;
46	    let headers = JSON_HEADERS;
47	    let body;
48	
49	    try {
50	      const route = await route_request(service, request, url, segments, idempotencyKey);
51	      status = route.status;
52	      headers = { ...(route.headers ?? JSON_HEADERS) };
53	      body = route.body;
54	      if (route.idempotent && typeof idempotencyKey === 'string' && idempotencyKey.length > 0) {
55	        await service.remember(route.operation, idempotencyKey, {
56	          status,
57	          body: route.body.toString('base64'),
58	        });
59	      }
60	    } catch (error) {
61	      if (error instanceof CachelatticeError) {
62	        status = error.status;
63	        const envelope = { error: { code: error.code, message: error.message } };
64	        if (error.details !== undefined) envelope.error.details = error.details;
65	        body = Buffer.from(`${canonicalJson(envelope)}\n`, 'utf8');
66	      } else {
67	        status = 500;
68	        body = Buffer.from(
69	          `${canonicalJson({ error: { code: 'internal_error', message: 'internal server error' } })}\n`,
70	          'utf8',
71	        );
72	        process.stderr.write(`cachelattice: ${error?.stack ?? error}\n`);
73	      }
74	      headers = JSON_HEADERS;
75	    }
76	
77	    response.writeHead(status, {
78	      ...headers,
79	      'content-length': String(body.length),
80	      connection: 'close',
81	    });
82	    response.end(body);
83	  });
84	
85	  server.on('clientError', (error, socket) => {
86	    if (socket.writable) socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n');
87	  });
88	
89	  return server;
90	}
91	
92	async function route_request(service, request, url, segments, idempotencyKey) {
93	  const method = request.method;
94	  const jsonOut = (status, value, extra = {}) => ({
95	    status,
96	    headers: JSON_HEADERS,
97	    body: Buffer.from(`${canonicalJson(value)}\n`, 'utf8'),
98	    ...extra,
99	  });
100	
101	  if (method === 'GET' && segments.length === 1 && segments[0] === 'health') {
102	    return jsonOut(200, { status: 'ok', service: 'cachelattice' });
103	  }
104	
105	  if (method === 'GET' && segments.length === 1 && segments[0] === 'actions') {
106	    return jsonOut(200, { actions: await service.listActions() });
107	  }
108	  if (method === 'GET' && segments.length === 2 && segments[0] === 'actions') {
109	    return jsonOut(200, await service.getAction(segments[1]));
110	  }
111	  if ((method === 'POST' || method === 'PUT') && segments.length === 1 && segments[0] === 'actions') {
112	    const body = parseJson(await readBody(request));
113	    const replayed = await service.recall('POST /actions', idempotencyKey);
114	    if (replayed) return jsonOut(replayed.status, JSON.parse(Buffer.from(replayed.body, 'base64').toString('utf8')));
115	    return jsonOut(201, await service.putAction(body), { idempotent: true, operation: 'POST /actions' });
116	  }
117	  if (method === 'PUT' && segments.length === 2 && segments[0] === 'actions') {
118	    const body = parseJson(await readBody(request));
119	    if (body.name !== undefined && body.name !== segments[1]) {
120	      throw new ValidationError('action body name must match the path name');
121	    }
122	    return jsonOut(200, await service.putAction({ ...body, name: segments[1] }, { refresh: true }));
123	  }
124	
125	  if (method === 'GET' && segments.length === 1 && segments[0] === 'graphs') {
126	    return jsonOut(200, { graphs: await service.listGraphs() });
127	  }
128	  if ((method === 'POST' || method === 'PUT') && segments.length === 1 && segments[0] === 'graphs') {
129	    const body = parseJson(await readBody(request));
130	    if (typeof body.id !== 'string') throw new ValidationError('graph body must carry an id');
131	    const replayed = await service.recall('POST /graphs', idempotencyKey);
132	    if (replayed) return jsonOut(replayed.status, JSON.parse(Buffer.from(replayed.body, 'base64').toString('utf8')));
133	    return jsonOut(201, await service.putGraph(body.id, body), { idempotent: true, operation: 'POST /graphs' });
134	  }
135	  if (method === 'PUT' && segments.length === 2 && segments[0] === 'graphs') {
136	    const body = parseJson(await readBody(request));
137	    if (body.id !== undefined && body.id !== segments[1]) {
138	      throw new ValidationError('graph body id must match the path id');
139	    }
140	    return jsonOut(200, await service.putGraph(segments[1], body));
141	  }
142	  if (method === 'GET' && segments.length === 2 && segments[0] === 'graphs') {
143	    return jsonOut(200, await service.getGraph(segments[1]));
144	  }
145	  if (method === 'POST' && segments.length === 3 && segments[0] === 'graphs' && segments[2] === 'run') {
146	    const raw = await readBody(request);
147	    const body = raw.length === 0 ? {} : parseJson(raw);
148	    for (const key of Object.keys(body)) {
149	      if (key !== 'use_cache') throw new ValidationError(`run request contains an unknown field: ${key}`);
150	    }
151	    const useCache = body.use_cache === undefined ? true : body.use_cache;
152	    if (typeof useCache !== 'boolean') throw new ValidationError('use_cache must be a boolean');
153	    const operation = `POST /graphs/${segments[1]}/run`;
154	    const replayed = await service.recall(operation, idempotencyKey);
155	    if (replayed) return jsonOut(replayed.status, JSON.parse(Buffer.from(replayed.body, 'base64').toString('utf8')));
156	    return jsonOut(200, await service.runGraph(segments[1], { useCache }), { idempotent: true, operation });
157	  }
158	  if (method === 'POST' && segments.length === 3 && segments[0] === 'graphs' && segments[2] === 'verify') {
159	    // Verify takes no parameters: the body is empty or exactly {}, so a typo in
160	    // a field name can never be silently ignored. Verification is read-only and
161	    // never participates in idempotency replay.
162	    const raw = await readBody(request);
163	    if (raw.length > 0) {
164	      const parsed = parseJson(raw);
165	      if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed) || Object.keys(parsed).length > 0) {
166	        throw new ValidationError('verify request body must be empty or {}');
167	      }
168	    }
169	    return jsonOut(200, await service.verifyGraph(segments[1]));
170	  }
171	
172	  if (method === 'GET' && segments.length === 1 && segments[0] === 'stats') {
173	    return jsonOut(200, await service.stats());
174	  }
175	  if (method === 'GET' && segments.length === 1 && segments[0] === 'cache') {
176	    return jsonOut(200, { entries: await service.cacheEntries() });
177	  }
178	  if (method === 'GET' && segments.length === 2 && segments[0] === 'cache') {
179	    const key = assertCacheKey(segments[1]);
180	    const { manifest, buffer } = await service.remoteRead(key);
181	    if (url.searchParams.get('meta') === '1') {
182	      return jsonOut(200, {
183	        key,
184	        action_id: manifest.action_id,
185	        digest: manifest.digest,
186	        size: manifest.size,
187	        command: manifest.command,
188	        key_schema: manifest.key_schema,
189	      });
190	    }
191	    return {
192	      status: 200,
193	      headers: {
194	        ...OCTET_HEADERS,
195	        'x-cache-key': key,
196	        'x-cache-digest': manifest.digest,
197	        'x-cache-size': String(buffer.length),
198	      },
199	      body: buffer,
200	    };
201	  }
202	  if (method === 'POST' && segments.length === 2 && segments[0] === 'cache' && segments[1] === 'gc') {
203	    const raw = await readBody(request);
204	    const body = raw.length === 0 ? {} : parseJson(raw);
205	    return jsonOut(200, await service.gc(body));
206	  }
207	  if ((method === 'PUT' || method === 'POST') && segments.length === 2 && segments[0] === 'cache') {
208	    const key = assertCacheKey(segments[1]);
209	    const buffer = await readBody(request);
210	    if (buffer.length === 0) throw new ValidationError('cache upload body must carry the artifact bytes');
211	    const entry = {
212	      action_id: request.headers['x-cache-action'] ?? 'remote',
213	      command: JSON.parse(request.headers['x-cache-command'] ?? 'null'),
214	      inputs: JSON.parse(request.headers['x-cache-inputs'] ?? 'null'),
215	      env: JSON.parse(request.headers['x-cache-env'] ?? 'null'),
216	    };
217	    const manifest = await service.cachePut(key, entry, buffer);
218	    return jsonOut(201, { key, digest: manifest.digest, size: manifest.size });
219	  }
220	
221	  throw new NotFoundError('route was not found');
222	}
