4	import { canonicalJson, digestOf, sha256Text, assertDigest } from './canonical.js';
5	import {
6	  CachelatticeError,
7	  ConflictError,
8	  NotFoundError,
9	  ReproducibilityMismatchError,
10	  ValidationError,
11	  VerificationUnavailableError,
12	} from './errors.js';
13	import { commandSources, executeArtifact, normalizeCommand } from './executor.js';
14	import {
15	  actionIdOf,
16	  actionKey,
17	  assertHash,
18	  assertName,
19	  normalizeCacheInputs,
20	  normalizeEnv,
21	  normalizeInputs,
22	  normalizePath,
23	  runKey,
24	  KEY_SCHEMA,
25	} from './key.js';
26	import { ObjectStore } from './store.js';
27	
28	export const MANIFEST_SCHEMA = 'cachelattice/manifest/v1';
29	export const RUN_SCHEMA = 'cachelattice/run/v1';
30	const VERIFY_SCHEMA = 'cachelattice/verify/v1';
31	const STATS_SCHEMA = 'cachelattice/stats/v1';
32	
33	const GRAPH_FIELDS = ['id', 'nodes', 'concurrency', 'limits'];
34	const NODE_FIELDS = ['id', 'action', 'needs', 'resources'];
35	const ACTION_FIELDS = ['name', 'command', 'inputs', 'env', 'depends_on'];
36	const INPUT_FIELDS = ['kind', 'path', 'digest'];
37	const CACHE_ENTRY_FIELDS = ['action_id', 'command', 'inputs', 'env', 'depends_on'];
38	
39	const HEX_KEY = /^[0-9a-f]{64}$/;
40	const ZERO_DIGEST = `sha256:${'0'.repeat(64)}`;
41	const RESOURCE_NAME = /^[A-Za-z][A-Za-z0-9_-]{0,31}$/;
42	const RESOURCE_MAX = 1000000;
43	
44	function rejectUnknown(object, allowed, label) {
45	  for (const key of Object.keys(object)) {
46	    if (!allowed.includes(key)) {
47	      throw new ValidationError(`${label} contains an unknown field: ${key}`);
48	    }
49	  }
50	}
51	
52	function isPlainObject(value) {
53	  return value !== null && typeof value === 'object' && !Array.isArray(value);
54	}
55	
56	function normalizeProducers(value, label) {
57	  if (!Array.isArray(value)) throw new ValidationError(`${label} depends_on must be an array of action names`);
58	  const names = value.map((name) => assertName(name, `${label} dependency`));
59	  if (new Set(names).size !== names.length) {
60	    throw new ValidationError(`${label} lists a dependency twice`);
61	  }
62	  return [...names].sort();
63	}
64	
65	// Resource declarations are scheduling hints only: they gate when a node may
66	// start, never what it computes, so they live outside every key, manifest and
67	// artifact. Both limits and resources are plain objects from a resource name to
68	// a non-negative integer amount.
69	function normalizeResourceMap(value, label, minimum) {
70	  if (!isPlainObject(value)) throw new ValidationError(`${label} must be a plain object`);
71	  const normalized = {};
72	  for (const [name, amount] of Object.entries(value)) {
73	    if (!RESOURCE_NAME.test(name)) {
74	      throw new ValidationError(
75	        `resource name must match [A-Za-z][A-Za-z0-9_-]{0,31}, received ${JSON.stringify(name)}`,
76	      );
77	    }
78	    if (!Number.isInteger(amount) || amount < minimum || amount > RESOURCE_MAX) {
79	      throw new ValidationError(`${label} ${name} must be an integer between ${minimum} and ${RESOURCE_MAX}`);
80	    }
81	    normalized[name] = amount;
82	  }
83	  return normalized;
84	}
85	
86	export function assertCacheKey(value) {
87	  if (typeof value !== 'string' || !HEX_KEY.test(value)) {
88	    throw new ValidationError(
89	      `cache key must be 64 lowercase hex characters, received ${JSON.stringify(value)}`,
90	    );
91	  }
92	  return value;
93	}
94	
95	// A node key is only salted when there is something to fold in, which keeps the
96	// root node key of a graph exactly equal to the action key it runs.
97	export function nodeKeyOf(actionKey, upstreamKeys) {
98	  if (upstreamKeys.length === 0) return actionKey;
99	  return sha256Text(
100	    `cachelattice/node-key/v1\n${actionKey}\n${[...upstreamKeys].sort().join('\n')}`,
101	  );
102	}
103	
104	export function dependencyRunKey(dependencies) {
105	  const lines = dependencies
106	    .map((dependency) => `${dependency.action_id}:${dependency.key}`)
107	    .join('\n');
108	  return sha256Text(`cachelattice/dependency-run/v1\n${lines}`);
109	}
110	
111	const byNodeId = (left, right) => (left.node_id < right.node_id ? -1 : left.node_id > right.node_id ? 1 : 0);
112	
113	// A miss and a hit must produce byte-identical manifests as well as
114	// byte-identical artifacts, so the manifest is derived purely from the action
115	// definition, the resolved dependency keys, and the artifact bytes. It carries
116	// no wall-clock timestamp, no node id, and no hint about whether it was
117	// recomputed or read back.
118	export function buildManifest({ actionId, key, command, inputs, env, dependencies, digest, size }) {
119	  return {
120	    schema: MANIFEST_SCHEMA,
121	    key_schema: KEY_SCHEMA,
122	    action_id: actionId,
123	    key,
124	    command,
125	    inputs,
126	    env,
127	    dependency_run_key: dependencyRunKey(dependencies),
128	    dependencies,
129	    digest: `sha256:${digest}`,
130	    size,
131	  };
132	}
133	
134	// Deterministic synthetic execution cost, so a graph run has the same shape on
135	// every machine and concurrency is observable without a real toolchain.
136	function syntheticDelay(command) {
137	  return 10 + (parseInt(sha256Text(canonicalJson(command)).slice(0, 4), 16) % 40);
138	}
139	
140	const sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds));
141	
142	export class Cachelattice {
143	  constructor({ dataDirectory, workspace, ambientEnv = process.env, clock = () => new Date() }) {
144	    this.store = new ObjectStore(dataDirectory);
145	    this.workspace = path.resolve(workspace);
146	    this.ambientEnv = ambientEnv;
147	    this.clock = clock;
148	    this.actions = new Map();
149	    this.graphs = new Map();
150	    this.runs = new Map();
151	    this.statsCache = null;
152	    this.loading = this.load();
153	  }
154	
155	  async load() {
156	    for (const entry of await this.readRegistry('actions')) this.actions.set(entry.name, entry);
157	    for (const entry of await this.readRegistry('graphs')) {
158	      // Graphs persisted before resource limits existed carry no declarations.
159	      entry.limits ??= {};
160	      for (const node of entry.nodes) node.resources ??= {};
161	      this.graphs.set(entry.id, entry);
162	    }
163	    for (const entry of await this.readRegistry('runs')) this.runs.set(entry.graph_id, entry);
164	    this.statsCache = (await this.store.readMeta('stats.json')) ?? this.blankStats();
165	  }
166	
167	  async readRegistry(kind) {
168	    const index = (await this.store.readMeta(`index/${kind}.json`)) ?? { items: [] };
169	    const items = [];
170	    for (const id of index.items) {
171	      const entry = await this.store.readMeta(`${kind}/${id}.json`);
172	      if (entry) items.push(entry);
173	    }
174	    return items;
175	  }
176	
177	  async writeRegistry(kind, id, entry) {
178	    await this.store.writeMeta(`${kind}/${id}.json`, entry);
179	    const index = (await this.store.readMeta(`index/${kind}.json`)) ?? { items: [] };
180	    if (!index.items.includes(id)) {
181	      await this.store.writeMeta(`index/${kind}.json`, { items: [...index.items, id].sort() });
182	    }
183	    return entry;
184	  }
185	
186	  blankStats() {
187	    return {
188	      schema: STATS_SCHEMA,
189	      actions_registered: 0,
190	      graphs_registered: 0,
191	      graph_runs: 0,
192	      nodes_scheduled: 0,
193	      cache_hits: 0,
194	      cache_misses: 0,
195	      artifacts_executed: 0,
196	      cache_writes: 0,
197	      remote_reads: 0,
198	      remote_writes: 0,
199	      cache_entries: 0,
200	    };
201	  }
202	
203	  async stats() {
204	    await this.loading;
205	    this.statsCache.cache_entries = (await this.store.listKeys(100000)).length;
206	    return { ...this.statsCache };
207	  }
208	
209	  bump(field, amount = 1) {
210	    this.statsCache[field] += amount;
211	  }
212	  async persistStats() {
213	    await this.store.writeMeta('stats.json', this.statsCache);
214	  }
215	
216	  actionView(action) {
217	    return {
218	      name: action.name,
219	      action_id: action.action_id,
220	      key: action.key,
221	      command: action.command,
222	      inputs: action.inputs,
223	      env: action.env.names,
224	      env_values: action.env.values,
225	      depends_on: action.depends_on,
226	    };
227	  }
228	
229	  graphView(graph) {
230	    return { id: graph.id, concurrency: graph.concurrency, limits: graph.limits, nodes: graph.nodes };
231	  }
232	
233	  // ---------------------------------------------------------------- actions
234	
235	  // Validates the declared input list and resolves each entry to the digest that
236	  // enters the key. File inputs are snapshotted here, at registration time, so an
237	  // action key stays stable when the workspace changes underneath it.
238	  async resolveInputs(declaredInputs) {
239	    if (!Array.isArray(declaredInputs) || declaredInputs.length === 0) {
240	      throw new ValidationError('action inputs must be a non-empty array');
241	    }
242	    const declared = normalizeInputs(
243	      declaredInputs.map((input) => {
244	        if (!isPlainObject(input)) throw new ValidationError('each input must be an object');
245	        rejectUnknown(input, INPUT_FIELDS, 'input');
246	        if (input.kind !== 'file' && input.kind !== 'hash') {
247	          throw new ValidationError('input kind must be "file" or "hash"');
248	        }
249	        if (input.kind === 'file' && 'digest' in input) {
250	          throw new ValidationError('a file input must not carry a digest; the service hashes it');
251	        }
252	        if (input.kind === 'hash' && !('digest' in input)) {
253	          throw new ValidationError('a hash input must carry a digest');
254	        }
255	        // normalizeInputs only sorts and de-duplicates; the real digest replaces
256	        // this placeholder below.
257	        return input.kind === 'file' ? { kind: 'file', path: input.path, digest: ZERO_DIGEST } : input;
258	      }),
259	    );
260	    const resolved = [];
261	    for (const input of declared) {
262	      resolved.push(
263	        input.kind === 'hash'
264	          ? { kind: 'hash', path: input.path, digest: assertHash(input.digest, 'input hash') }
265	          : { kind: 'file', path: input.path, digest: digestOf(await readWorkspaceFile(this.workspace, input.path)) },
266	      );
267	    }
268	    return resolved;
269	  }
270	
271	  async putAction(body, { refresh = false } = {}) {
272	    await this.loading;
273	    if (!isPlainObject(body)) throw new ValidationError('request body must be a JSON object');
274	    rejectUnknown(body, ACTION_FIELDS, 'action');
275	    const name = assertName(body.name, 'action name');
276	    if (!isPlainObject(body.command)) throw new ValidationError('action command must be an object');
277	    if (!Array.isArray(body.env)) throw new ValidationError('action env must be an array of names');
278	    const inputs = await this.resolveInputs(body.inputs);
279	
280	    const command = normalizeCommand(body.command);
281	    for (const source of commandSources(command)) {
282	      const normalized = normalizePath(source, 'command source');
283	      if (!inputs.some((input) => input.path === normalized)) {
284	        throw new ValidationError(`command reads ${normalized}, which is not a declared input`);
285	      }
286	    }
287	    if (command.kind === 'concat-text' && command.sources.length === 0) {
288	      throw new ValidationError('command sources must not be empty');
289	    }
290	
291	    // A declared producer must exist and must have produced one of the hash
292	    // inputs. This keeps the causal chain honest: a consumer's key can only move
293	    // for a producer whose artifact it actually consumes.
294	    const dependsOn = normalizeProducers(body.depends_on ?? [], `action ${name}`);
295	    for (const producerName of dependsOn) {
296	      const producer = this.actions.get(producerName);
297	      if (!producer) throw new ValidationError(`action ${name} depends on unregistered action ${producerName}`);
298	      if (!inputs.some((input) => input.kind === 'hash' && input.digest === producer.key)) {
299	        throw new ValidationError(
300	          `action ${name} depends on ${producerName} but does not declare its artifact as a hash input`,
301	        );
302	      }
303	    }
304	    const env = normalizeEnv(body.env, this.ambientEnv);
305	    const entry = {
306	      name,
307	      action_id: actionIdOf(name),
308	      command,
309	      inputs,
310	      env,
311	      // The artifact of every producer named here must be declared as a hash
312	      // input, and the graph must wire exactly these producers as `needs`. The
313	      // producer *keys* are folded into the node key at run time (see plan()),
314	      // which is what makes an upstream change invalidate everything below it.
315	      depends_on: dependsOn,
316	    };
317	    entry.key = actionKey({ command: entry.command, inputs, env });
318	
319	    // A name identifies one action. Registering it again is a conflict no matter
320	    // how similar the definition is, so that replacing an action is always the
321	    // explicit, reviewable act of a PUT.
322	    const previous = this.actions.get(name);
323	    if (previous && !refresh) {
324	      throw new ConflictError(
325	        `action ${name} is already registered; PUT /actions/${name} to replace it`,
326	      );
327	    }
328	    this.actions.set(name, entry);
329	    if (!previous) this.bump('actions_registered');
330	    await this.writeRegistry('actions', name, entry);
331	    await this.persistStats();
332	    return this.actionView(entry);
333	  }
334	
335	  async getAction(name) {
336	    await this.loading;
