351	  async putGraph(graphId, body) {
352	    await this.loading;
353	    const id = assertName(graphId, 'graph id');
354	    if (!isPlainObject(body)) throw new ValidationError('request body must be a JSON object');
355	    rejectUnknown(body, GRAPH_FIELDS, 'graph');
356	    if (body.id !== undefined && body.id !== id) {
357	      throw new ValidationError('graph body id must match the path id');
358	    }
359	    if (!Array.isArray(body.nodes) || body.nodes.length === 0) {
360	      throw new ValidationError('graph nodes must be a non-empty array');
361	    }
362	    const concurrency = body.concurrency === undefined ? 1 : body.concurrency;
363	    if (!Number.isInteger(concurrency) || concurrency < 1 || concurrency > 64) {
364	      throw new ValidationError('graph concurrency must be an integer between 1 and 64');
365	    }
366	    const limits = normalizeResourceMap(body.limits === undefined ? {} : body.limits, 'graph limits', 1);
367	
368	    const nodes = body.nodes.map((node) => {
369	      if (!isPlainObject(node)) throw new ValidationError('each graph node must be an object');
370	      rejectUnknown(node, NODE_FIELDS, 'graph node');
371	      const nodeId = assertName(node.id, 'node id');
372	      const action = assertName(node.action, 'node action');
373	      const needs = node.needs === undefined ? [] : node.needs;
374	      if (!Array.isArray(needs)) throw new ValidationError(`node ${nodeId} needs must be an array`);
375	      if (new Set(needs).size !== needs.length) {
376	        throw new ValidationError(`node ${nodeId} lists a dependency twice`);
377	      }
378	      for (const dependency of needs) assertName(dependency, `node ${nodeId} dependency`);
379	      const resources = normalizeResourceMap(
380	        node.resources === undefined ? {} : node.resources,
381	        `node ${nodeId} resources`,
382	        0,
383	      );
384	      // Every reserved resource must be backed by a graph-level quota, and one
385	      // node may never ask for more than the whole graph allows.
386	      for (const [name, amount] of Object.entries(resources)) {
387	        if (!(name in limits)) {
388	          throw new ValidationError(`node ${nodeId} reserves resource ${name}, which has no graph limit`);
389	        }
390	        if (amount > limits[name]) {
391	          throw new ValidationError(
392	            `node ${nodeId} reserves ${amount} of ${name}, over the graph limit of ${limits[name]}`,
393	          );
394	        }
395	      }
396	      return { id: nodeId, action, needs: [...needs].sort(), resources };
397	    });
398	
399	    const seen = new Set();
400	    for (const node of nodes) {
401	      if (seen.has(node.id)) throw new ValidationError(`duplicate node id: ${node.id}`);
402	      for (const dependency of node.needs) {
403	        if (dependency === node.id) throw new ValidationError(`node ${node.id} needs itself`);
404	        if (!seen.has(dependency)) {
405	          throw new ValidationError(
406	            `node ${node.id} needs ${dependency}, which is not defined earlier in the graph; a dependency cycle is not allowed`,
407	          );
408	        }
409	      }
410	      if (!this.actions.has(node.action)) {
411	        throw new ValidationError(`node ${node.id} references unregistered action ${node.action}`);
412	      }
413	      seen.add(node.id);
414	    }
415	
416	    const entry = { id, concurrency, limits, nodes };
417	    const existed = this.graphs.has(id);
418	    this.graphs.set(id, entry);
419	    if (!existed) this.bump('graphs_registered');
420	    await this.writeRegistry('graphs', id, entry);
421	    await this.persistStats();
422	    return this.graphView(entry);
423	  }
