459	  // --------------------------------------------------------------- planning
460	
461	  // Resolves every node to a concrete action key. A node's key folds in the keys
462	  // of every action it needs, so a change anywhere upstream moves every key
463	  // downstream of it.
464	  plan(graphId) {
465	    const graph = this.graphs.get(graphId);
466	    if (!graph) throw new NotFoundError(`graph ${graphId} is not registered`);
467	    const byId = new Map(graph.nodes.map((node) => [node.id, node]));
468	    const planned = new Map();
469	
470	    const visit = (nodeId, trail) => {
471	      const known = planned.get(nodeId);
472	      if (known) return known;
473	      if (trail.has(nodeId)) {
474	        throw new ConflictError(`graph ${graphId} contains a dependency cycle through ${nodeId}`);
475	      }
476	      trail.add(nodeId);
477	      const node = byId.get(nodeId);
478	      if (!node) throw new ValidationError(`graph ${graphId} has no node ${nodeId}`);
479	      const action = this.actions.get(node.action);
480	      if (!action) {
481	        throw new ConflictError(`node ${nodeId} references action ${node.action}, which no longer exists`);
482	      }
483	      const upstream = node.needs.map((needed) => visit(needed, trail));
484	      const produced = upstream.map((entry) => entry.action.name).sort();
485	      const declared = action.depends_on;
486	      if (produced.join('\n') !== declared.join('\n')) {
487	        throw new ConflictError(
488	          `node ${nodeId} is wired to [${produced.join(', ')}] but action ${action.name} declares ` +
489	            `depends_on [${declared.join(', ')}]; re-register the action or rewire the graph`,
490	        );
491	      }
492	      const key = nodeKeyOf(action.key, upstream.map((entry) => entry.key));
493	      trail.delete(nodeId);
494	      const resolved = {
495	        node,
496	        action,
497	        key,
498	        dependencies: upstream
499	          .map((entry) => ({ action_id: entry.action.name, key: entry.key }))
500	          .sort((left, right) =>
501	            left.action_id < right.action_id ? -1 : left.action_id > right.action_id ? 1 : 0,
502	          ),
503	      };
504	      planned.set(nodeId, resolved);
505	      return resolved;
506	    };
507	
508	    for (const node of graph.nodes) visit(node.id, new Set());
509	    return planned;
510	  }
