512	  // -------------------------------------------------------------- execution
513	
514	  async runGraph(graphId, { useCache = true } = {}) {
515	    await this.loading;
516	    const graph = this.graphs.get(graphId);
517	    if (!graph) throw new NotFoundError(`graph ${graphId} is not registered`);
518	    const planned = this.plan(graphId);
519	    const key = runKey(
520	      graph.nodes.map((node) => ({ action_id: planned.get(node.id).action.name, key: planned.get(node.id).key })),
521	    );
522	
523	    // A run is always scheduled; there is no whole-run fast path, because the
524	    // answer to "was this a cache hit?" must come from the store on every run.
525	    // `plan_reused` only reports that no key moved since the previous run.
526	    const previous = this.runs.get(graphId) ?? null;
527	    const stale = graph.nodes.flatMap((node) => {
528	      const before = previous?.nodes.find((candidate) => candidate.id === node.id);
529	      const action = planned.get(node.id);
530	      return before && before.key !== action.key
531	        ? [{ id: node.id, action: action.action.name, was: before.key, now: action.key }]
532	        : [];
533	    });
534	    const planReused = previous !== null && previous.run_key === key;
535	
536	    const state = new Map(graph.nodes.map((node) => [node.id, { node, status: 'pending' }]));
537	    const isReady = (id) =>
538	      state.get(id).status === 'pending' &&
539	      state.get(id).node.needs.every((needed) => state.get(needed).status === 'done');
540	    const readyIds = () => graph.nodes.map((node) => node.id).filter(isReady).sort();
541	
542	    let hits = 0;
543	    let misses = 0;
544	    let inFlight = 0;
545	    let peakParallel = 0;
546	    const startedAt = Date.now();
547	    this.bump('graph_runs');
548	    this.bump('nodes_scheduled', graph.nodes.length);
549	
550	    // Resource bookkeeping for this run only; quotas never leak across graphs.
551	    // `reserved` is what running nodes currently hold, `peak` the high-water
552	    // mark, with every declared limit present from the start so an unused
553	    // resource reports a peak of 0.
554	    const reserved = {};
555	    const peakResources = {};
556	    for (const name of Object.keys(graph.limits)) {
557	      reserved[name] = 0;
558	      peakResources[name] = 0;
559	    }
560	    const fits = (resources) =>
561	      Object.entries(resources).every(([name, amount]) => reserved[name] + amount <= graph.limits[name]);
562	    const reserve = (resources) => {
563	      for (const [name, amount] of Object.entries(resources)) {
564	        reserved[name] += amount;
565	        peakResources[name] = Math.max(peakResources[name], reserved[name]);
566	      }
567	    };
568	    const release = (resources) => {
569	      for (const [name, amount] of Object.entries(resources)) reserved[name] -= amount;
570	    };
571	
572	    const results = [];
573	    while (results.length < graph.nodes.length) {
574	      // Deterministic dispatch order: lexicographic by node id. A candidate
575	      // starts only when the concurrency budget and every resource it reserves
576	      // fit; one that does not fit is skipped for now, so a resource-hungry
577	      // candidate never blocks later ready nodes. Concurrency remains the only
578	      // source of timing freedom and never changes an artifact.
579	      for (const id of readyIds()) {
580	        if (inFlight >= graph.concurrency) break;
581	        const entry = state.get(id);
582	        if (!fits(entry.node.resources)) continue;
583	        entry.status = 'running';
584	        reserve(entry.node.resources);
585	        inFlight += 1;
586	        peakParallel = Math.max(peakParallel, inFlight);
587	        const dependencies = entry.node.needs.map((needed) => {
588	          const produced = state.get(needed).result;
589	          return { action_id: produced.action_id, key: produced.key };
590	        });
591	        entry.promise = this.executeNode(planned.get(entry.node.id), dependencies, { useCache })
592	          .then((outcome) => {
593	            entry.status = 'done';
594	            entry.result = outcome;
595	            results.push(outcome);
596	            if (outcome.cache === 'hit') hits += 1;
597	            else misses += 1;
598	          })
599	          .catch((error) => {
600	            entry.status = 'failed';
601	            entry.error = error;
602	          })
603	          .finally(() => {
604	            release(entry.node.resources);
605	            inFlight -= 1;
606	          });
607	      }
608	      const running = [...state.values()].filter((entry) => entry.status === 'running');
609	      if (running.length === 0) {
610	        // A failed node must surface as a failed request, never as a hang.
611	        const failed = [...state.values()].find((entry) => entry.status === 'failed');
612	        if (failed) throw failed.error;
613	        if (results.length < graph.nodes.length) {
614	          throw new ConflictError(`graph ${graphId} has no schedulable node; check its dependencies`);
615	        }
616	        break;
617	      }
618	      await Promise.all(running.map((entry) => entry.promise));
619	    }
620	
621	    const nodes = results
622	      .map((result) => ({
623	        id: result.id,
624	        action: result.action_id,
625	        key: result.key,
626	        digest: result.digest,
627	        size: result.size,
628	        cache: result.cache,
629	        dependencies: result.dependencies,
630	        resources: { ...result.resources },
631	      }))
632	      .sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));
633	
634	    const record = {
635	      schema: RUN_SCHEMA,
636	      graph_id: graphId,
637	      run_key: key,
638	      completed_at: this.clock().toISOString(),
639	      concurrency: graph.concurrency,
640	      duration_ms: Date.now() - startedAt,
641	      peak_parallel: peakParallel,
642	      plan_reused: planReused,
643	      cache_hits: hits,
644	      cache_misses: misses,
645	      stale_nodes: stale,
646	      resource_limits: { ...graph.limits },
647	      peak_resources: { ...peakResources },
648	      nodes,
649	    };
650	    this.runs.set(graphId, record);
651	    await this.writeRegistry('runs', graphId, record);
652	    this.bump('cache_hits', hits);
653	    this.bump('cache_misses', misses);
654	    await this.persistStats();
655	
656	    return {
657	      graph_id: graphId,
658	      run_key: key,
659	      plan_reused: planReused,
660	      cache_hits: hits,
661	      cache_misses: misses,
662	      peak_parallel: peakParallel,
663	      resource_limits: { ...graph.limits },
664	      peak_resources: { ...peakResources },
665	      stale_nodes: stale,
666	      nodes,
667	    };
668	  }
669	
670	  async executeNode(planned, dependencies, { useCache }) {
671	    const { node, action, key } = planned;
672	    if (useCache && this.store.hasManifest(key)) {
673	      const { manifest } = await this.store.readArtifact(key);
674	      this.assertManifestMatches(manifest, action, key);
675	      return {
676	        id: node.id,
677	        action_id: action.name,
678	        key,
679	        digest: manifest.digest,
680	        size: manifest.size,
681	        cache: 'hit',
682	        dependencies,
683	        resources: node.resources,
684	      };
685	    }
686	
687	    await sleep(syntheticDelay(action.command));
688	    const buffer = await executeArtifact({
689	      command: action.command,
690	      inputs: action.inputs,
691	      env: action.env,
692	      dependencies,
693	      workspace: this.workspace,
694	    });
695	    const digest = await this.store.writeBlob(buffer);
696	    const manifest = buildManifest({
697	      actionId: action.name,
698	      key,
699	      command: action.command,
700	      inputs: action.inputs,
701	      env: action.env,
702	      dependencies,
703	      digest,
704	      size: buffer.length,
705	    });
706	    // A concurrent miss for the same key may have won the race. The manifests
707	    // are identical by construction, so the winner is irrelevant; the blob is
708	    // content-addressed, so there is only ever one possibility.
709	    if (!this.store.hasManifest(key)) await this.store.writeManifest(key, manifest);
710	    this.bump('artifacts_executed');
711	    this.bump('cache_writes');
712	    return {
713	      id: node.id,
714	      action_id: action.name,
715	      key,
716	      digest: manifest.digest,
717	      size: manifest.size,
718	      cache: 'miss',
719	      dependencies,
720	      resources: node.resources,
721	    };
722	  }
723	
724	  // ---------------------------------------------------------------- verify
725	
726	  // Reproducible-build verification against the most recent successful run.
727	  // Unlike runGraph({use_cache:false}) this path is strictly read-only: it
728	  // never writes a blob or manifest, never moves last_run or idempotency
729	  // records, never bumps a counter, and never touches the workspace. Each node
730	  // key from the reference run locates a manifest and its blob, the manifest is
731	  // address-checked (its frozen fields must recompute to the node key) and the
732	  // blob digest-checked, then the frozen command is re-executed in memory and
733	  // its digest and size are compared with what the cache holds.
734	  async verifyGraph(graphId) {
735	    await this.loading;
736	    const graph = this.graphs.get(graphId);
737	    if (!graph) throw new NotFoundError(`graph ${graphId} is not registered`);
738	    // A run record exists only for a run that completed every node, so this is
739	    // exactly "the graph has one successful run".
740	    const reference = this.runs.get(graphId);
741	    if (!reference) {
742	      throw new VerificationUnavailableError(
743	        `graph ${graphId} has no successful run to verify; run it before verifying`,
744	      );
745	    }
746	
747	    // Each distinct node key is located and re-executed once; two nodes that
748	    // share one key (identical definitions) still each get their own verified
749	    // entry afterwards.
750	    const reexecuted = new Map();
751	    const unavailable = (nodeId, reason) => {
752	      throw new VerificationUnavailableError(
753	        `verification of graph ${graphId} is unavailable for node ${nodeId}: ${reason}`,
754	      );
755	    };
756	
757	    for (const node of reference.nodes) {
758	      if (reexecuted.has(node.key)) continue;
759	      let entry;
760	      try {
761	        entry = await this.store.readArtifact(node.key);
762	      } catch (error) {
763	        if (error instanceof NotFoundError || error instanceof ValidationError) {
764	          unavailable(node.id, error.message);
765	        }
766	        throw error;
767	      }
768	      const { manifest, buffer } = entry;
769	
770	      // The run record and the manifest must describe the same artifact.
771	      if (manifest.digest !== node.digest || manifest.size !== node.size) {
772	        unavailable(
773	          node.id,
774	          `the cache manifest for key ${node.key} does not describe the artifact recorded by run ${reference.run_key}`,
775	        );
776	      }
777	
778	      // Address validation: the frozen command, inputs, environment and
779	      // dependency node keys must recompute to exactly the node key that named
780	      // this manifest, and the stored bytes must be the bytes it names.
781	      const recomputedKey = nodeKeyOf(
782	        actionKey({ command: manifest.command, inputs: manifest.inputs, env: manifest.env }),
783	        manifest.dependencies.map((dependency) => dependency.key),
784	      );
785	      if (recomputedKey !== manifest.key) {
786	        unavailable(node.id, `cache manifest for key ${node.key} fails address validation`);
787	      }
788	      if (digestOf(buffer) !== manifest.digest) {
789	        unavailable(node.id, `cache blob for key ${node.key} fails digest validation`);
790	      }
791	
792	      let recomputed;
793	      try {
794	        recomputed = await executeArtifact({
795	          command: manifest.command,
796	          inputs: manifest.inputs,
797	          env: manifest.env,
798	          dependencies: manifest.dependencies,
799	          workspace: this.workspace,
800	        });
801	      } catch (error) {
802	        if (error instanceof CachelatticeError) unavailable(node.id, error.message);
803	        throw error;
804	      }
805	      reexecuted.set(node.key, { digest: digestOf(recomputed), size: recomputed.length });
806	    }
807	
808	    const mismatches = [];
809	    const verified = [];
810	    for (const node of reference.nodes) {
811	      const expected = { digest: node.digest, size: node.size };
812	      const actual = reexecuted.get(node.key);
813	      if (actual.digest !== expected.digest || actual.size !== expected.size) {
814	        mismatches.push({
815	          node_id: node.id,
816	          expected_digest: expected.digest,
817	          expected_size: expected.size,
818	          actual_digest: actual.digest,
819	          actual_size: actual.size,
820	        });
821	      } else {
822	        verified.push({ node_id: node.id, key: node.key, digest: expected.digest, size: expected.size });
823	      }
824	    }
825	    verified.sort(byNodeId);
826	    mismatches.sort(byNodeId);
827	
828	    if (mismatches.length > 0) throw new ReproducibilityMismatchError(mismatches);
829	
830	    return {
831	      schema: VERIFY_SCHEMA,
832	      graph_id: graphId,
833	      reference_run_key: reference.run_key,
834	      verified,
835	    };
836	  }
