847	  // Ingest an action manifest. Any peer that knows a cached action key may push
848	  // the entry, and it is accepted only when every hashed field in the manifest
849	  // still recomputes to the key being claimed.
850	  async cachePut(key, entry, buffer) {
851	    await this.loading;
852	    const normalized = assertCacheKey(key);
853	    if (!isPlainObject(entry)) throw new ValidationError('cache entry must be a JSON object');
854	    rejectUnknown(entry, CACHE_ENTRY_FIELDS, 'cache entry');
855	    if (!isPlainObject(entry.command)) throw new ValidationError('cache entry command must be an object');
856	    if (!Array.isArray(entry.inputs) || !Array.isArray(entry.env)) {
857	      throw new ValidationError('cache entry inputs and env must be arrays');
858	    }
859	    for (const input of entry.inputs) {
860	      if (!isPlainObject(input)) throw new ValidationError('cache entry inputs must be objects');
861	      rejectUnknown(input, INPUT_FIELDS, 'cache entry input');
862	      if (input.kind !== 'file' && input.kind !== 'hash') {
863	        throw new ValidationError('cache entry input kind must be "file" or "hash"');
864	      }
865	    }
866	    const command = normalizeCommand(entry.command);
867	    const inputsValue = normalizeCacheInputs(entry.inputs);
868	    const names = entry.env.map((name) => {
869	      if (typeof name !== 'string' || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) {
870	        throw new ValidationError('cache entry env must be an array of variable names');
871	      }
872	      return name;
873	    });
874	    if (new Set(names).size !== names.length) {
875	      throw new ValidationError('cache entry env names must be unique');
876	    }
877	    // Copied so the manifest never aliases caller-owned state.
878	    const inputs = inputsValue.map((input) => ({ ...input }));
879	    const env = { names: [...names].sort(), values: {} };
880	    const recomputed = actionKey({ command, inputs, env });
881	    if (recomputed !== normalized) {
882	      throw new ValidationError(
883	        `cache entry does not describe key ${normalized}: the same fields hash to ${recomputed}`,
884	      );
885	    }
886	    const manifestKey = normalized;
887	    if (this.store.hasManifest(manifestKey)) {
888	      throw new ConflictError(`cache entry ${normalized} already exists`);
889	    }
890	    const digest = await this.store.writeBlob(buffer);
891	    // A remote entry carries no resolved dependency keys, so it is only ever
892	    // reachable as the entry of a root node - exactly the entries a peer can
893	    // hand over without shipping its whole graph.
894	    const manifest = buildManifest({
895	      actionId: entry.action_id ?? 'remote',
896	      key: normalized,
897	      command,
898	      inputs,
899	      env,
900	      dependencies: [],
901	      digest,
902	      size: buffer.length,
903	    });
904	    await this.store.writeManifest(manifestKey, manifest);
905	    this.bump('remote_writes');
906	    this.bump('cache_writes');
907	    await this.persistStats();
908	    return manifest;
909	  }
