911	  async remoteRead(key) {
912	    await this.loading;
913	    const entry = await this.cacheGet(key);
914	    this.bump('remote_reads');
915	    await this.persistStats();
916	    return entry;
917	  }
918	
919	  async cacheEntries(limit = 500) {
920	    await this.loading;
921	    return this.store.listKeys(limit);
922	  }
923	
924	  // --------------------------------------------------------------------- gc
925	
926	  // Cache retention. The keep set is the node keys of every registered graph's
927	  // last run plus whatever the caller asked to keep; a graph that never ran
928	  // contributes nothing. Every manifest is scanned and validated first, so a
929	  // corrupt store fails the whole request before a single object is deleted.
930	  // Everything outside the keep set is collected: the manifests, the blobs only
931	  // they referenced, and orphan blobs. A dry run reports the exact same sets
932	  // and byte counts without deleting anything.
933	  async gc(request = {}) {
934	    await this.loading;
935	    if (!isPlainObject(request)) throw new ValidationError('gc request must be a JSON object');
936	    rejectUnknown(request, ['keep', 'dry_run'], 'gc request');
937	    const dryRun = request.dry_run === undefined ? false : request.dry_run;
938	    if (typeof dryRun !== 'boolean') throw new ValidationError('gc dry_run must be a boolean');
939	    const keepRequested = new Set();
940	    if (request.keep !== undefined) {
941	      if (!Array.isArray(request.keep)) throw new ValidationError('gc keep must be an array of cache keys');
942	      for (const key of request.keep) keepRequested.add(assertCacheKey(key));
943	    }
944	
945	    const keep = new Set(keepRequested);
946	    for (const run of this.runs.values()) {
947	      for (const node of run.nodes) keep.add(node.key);
948	    }
949	
950	    // Validate before anything is deleted: an unreadable manifest, a key
951	    // mismatch, a missing or dishonest digest, or a missing or tampered blob
952	    // fails the request and leaves the store untouched.
953	    const keys = await this.store.listKeys(Number.MAX_SAFE_INTEGER);
954	    const manifests = new Map();
955	    for (const key of keys) {
956	      const manifest = await this.store.readManifest(key);
957	      const digest = assertDigest(manifest.digest, `cache manifest for key ${key} digest`);
958	      const hexDigest = digest.slice('sha256:'.length);
959	      let buffer;
960	      try {
961	        buffer = await readFile(this.store.blobPath(hexDigest));
962	      } catch (error) {
963	        if (error.code === 'ENOENT') {
964	          throw new ValidationError(
965	            `cache manifest for key ${key} references a blob that is missing from the object store`,
966	          );
967	        }
968	        throw error;
969	      }
970	      if (digestOf(buffer) !== digest) {
971	        throw new ValidationError(`blob referenced by cache manifest for key ${key} does not match its digest`);
972	      }
973	      manifests.set(key, hexDigest);
974	    }
975	
976	    for (const key of keepRequested) {
977	      if (!manifests.has(key)) throw new NotFoundError(`keep key ${key} does not name a cache entry`);
978	    }
979	
980	    const keptKeys = keys.filter((key) => keep.has(key));
981	    const removedKeys = keys.filter((key) => !keep.has(key));
982	    const keptDigests = new Set(keptKeys.map((key) => manifests.get(key)));
983	
984	    const blobSizes = new Map();
985	    for (const hexDigest of await this.store.listBlobDigests()) {
986	      blobSizes.set(hexDigest, (await stat(this.store.blobPath(hexDigest))).size);
987	    }
988	    let keptBytes = 0;
989	    for (const hexDigest of keptDigests) keptBytes += blobSizes.get(hexDigest);
990	    const removedDigests = [...blobSizes.keys()].filter((hexDigest) => !keptDigests.has(hexDigest));
991	    let removedBytes = 0;
992	    for (const hexDigest of removedDigests) removedBytes += blobSizes.get(hexDigest);
993	
994	    if (!dryRun) {
995	      for (const key of removedKeys) await this.store.deleteManifest(key);
996	      for (const hexDigest of removedDigests) await this.store.deleteBlob(hexDigest);
997	    }
998	
999	    return {
1000	      dry_run: dryRun,
1001	      kept_keys: keptKeys,
1002	      removed_keys: removedKeys,
1003	      removed_digests: removedDigests.map((hexDigest) => `sha256:${hexDigest}`),
1004	      kept_bytes: keptBytes,
1005	      removed_bytes: removedBytes,
1006	    };
1007	  }
1008	
1009	  // ----------------------------------------------------------- idempotency
1010	
1011	  async recall(operation, idempotencyKey) {
1012	    await this.loading;
1013	    if (typeof idempotencyKey !== 'string' || idempotencyKey.length === 0) return null;
1014	    if (idempotencyKey.length > 255) {
1015	      throw new ValidationError('Idempotency-Key must be at most 255 characters');
1016	    }
1017	    const record = await this.store.readMeta(
1018	      `idempotency/${sha256Text(`${operation}\n${idempotencyKey}`)}.json`,
1019	    );
1020	    return record ? { status: record.status, body: record.body } : null;
1021	  }
1022	
1023	  async remember(operation, idempotencyKey, response) {
1024	    await this.loading;
1025	    if (typeof idempotencyKey !== 'string' || idempotencyKey.length === 0) return;
1026	    await this.store.writeMeta(
1027	      `idempotency/${sha256Text(`${operation}\n${idempotencyKey}`)}.json`,
1028	      {
1029	        schema: 'cachelattice/idempotency/v1',
1030	        operation,
1031	        status: response.status,
1032	        body: response.body,
1033	      },
1034	    );
1035	  }
1036	
1037	  // A cache entry is valid for a node when the manifest's hashed fields still
1038	  // describe the action the node runs: same command, same input digests, same
1039	  // environment variable names. The action_id is provenance only - two
1040	  // differently named actions with the same definition legitimately share one
1041	  // entry, and the first one to run wins the label.
1042	  assertManifestMatches(manifest, action, key) {
1043	    if (manifest.key !== key) {
1044	      throw new ConflictError(`cache entry ${key} claims to belong to ${manifest.key}`);
1045	    }
1046	    const shape = (command, inputs, envNames) =>
1047	      canonicalJson({ command, inputs, env_names: envNames });
1048	    if (
1049	      shape(manifest.command, manifest.inputs, manifest.env.names) !==
1050	      shape(action.command, action.inputs, action.env.names)
1051	    ) {
1052	      throw new ConflictError(`cache entry for ${key} was produced from different inputs`);
1053	    }
1054	  }
1055	}
1056	
1057	export async function readWorkspaceFile(workspace, relative) {
1058	  const absolute = path.join(workspace, relative);
1059	  if (absolute !== workspace && !absolute.startsWith(workspace + path.sep)) {
1060	    throw new ValidationError(`path escapes the workspace: ${relative}`);
1061	  }
1062	  let info;
1063	  try {
1064	    info = await stat(absolute);
1065	  } catch (error) {
1066	    if (error.code === 'ENOENT') throw new ValidationError(`input file does not exist: ${relative}`);
1067	    throw error;
1068	  }
1069	  if (!info.isFile()) throw new ValidationError(`input path is not a regular file: ${relative}`);
1070	  return readFile(absolute);
1071	}
